"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { User, Mail, Lock, Phone, MapPin, Eye, EyeOff, Loader2 } from "lucide-react";
import { authApi } from "@/app/api_Client/auth.api";

export default function RegisterForm() {
  const router = useRouter();

  // 1. Quản lý trạng thái nhập liệu của các ô input
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    password: "",
    phoneNumber: "",
    address: "",
  });

  // 2. Quản lý trạng thái lỗi, loading và ẩn/hiện mật khẩu
  const [errors, setErrors] = useState<Record<string, string[]>>({});
  const [serverError, setServerError] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");

  // Hàm tự động cập nhật khi người dùng gõ phím
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));

    // Xóa dòng lỗi màu đỏ của ô đó ngay khi người dùng bắt đầu gõ sửa lại
    if (errors[name]) {
      setErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[name];
        return newErrors;
      });
    }
  };

  // Hàm xử lý gửi form (GỌI QUA authApi)
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setServerError("");
    setErrors({});

    try {
      // 🚀 GỌI QUA TẦNG API CLIENT CHUYÊN NGHIỆP:
      const res: any = await authApi.register(formData);

      setSuccessMessage(res.message || "Chúc mừng bạn đăng ký tài khoản thành công!");

      setTimeout(() => {
        router.push("/login"); // Tự động chuyển sang trang Đăng nhập sau 2 giây
      }, 2000);
    } catch (err: any) {
      if (err.response) {
        const { status, data } = err.response;

        if (status === 400 && data.error) {
          // Lỗi do Zod bắt (ví dụ: thiếu chữ hoa, thiếu số...)
          setErrors(data.error);
        } else {
          // Lỗi nghiệp vụ (ví dụ: Email đã trùng lặp 409) hoặc lỗi máy chủ (500)
          setServerError(data.message || "Đăng ký không thành công!");
        }
      } else {
        setServerError("Không thể kết nối đến máy chủ. Vui lòng kiểm tra lại mạng!");
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md p-8 bg-white dark:bg-neutral-900 rounded-2xl shadow-xl border border-neutral-200 dark:border-neutral-800">
      <div className="text-center mb-8">
        <h1 className="text-2xl font-bold text-neutral-900 dark:text-white">
          Tạo Tài Khoản Mới
        </h1>
        <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-2">
          Đăng ký để trải nghiệm mua sắm đồ điện tử và nhận tư vấn AI
        </p>
      </div>

      {/* Thông báo lỗi từ máy chủ nếu có */}
      {serverError && (
        <div className="mb-6 p-4 text-sm text-red-600 bg-red-50 dark:bg-red-950/50 dark:text-red-400 rounded-xl border border-red-200 dark:border-red-900">
          {serverError}
        </div>
      )}

      {/* Thông báo thành công */}
      {successMessage && (
        <div className="mb-6 p-4 text-sm text-emerald-600 bg-emerald-50 dark:bg-emerald-950/50 dark:text-emerald-400 rounded-xl border border-emerald-200 dark:border-emerald-900">
          {successMessage}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* 1. Họ và tên */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">
            Họ và tên <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <User className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-neutral-400" />
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleChange}
              placeholder="Nguyễn Văn A"
              required
              className="w-full pl-11 pr-4 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 rounded-xl text-neutral-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-600"
            />
          </div>
          {errors.name && (
            <p className="text-xs text-red-500 mt-1">{errors.name[0]}</p>
          )}
        </div>

        {/* 2. Địa chỉ Email */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">
            Email <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Mail className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-neutral-400" />
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="email@example.com"
              required
              className="w-full pl-11 pr-4 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 rounded-xl text-neutral-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-600"
            />
          </div>
          {errors.email && (
            <p className="text-xs text-red-500 mt-1">{errors.email[0]}</p>
          )}
        </div>

        {/* 3. Mật khẩu */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">
            Mật khẩu bảo mật <span className="text-red-500">*</span>
          </label>
          <div className="relative">
            <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-neutral-400" />
            <input
              type={showPassword ? "text" : "password"}
              name="password"
              value={formData.password}
              onChange={handleChange}
              placeholder="Tối thiểu 8 ký tự, hoa, thường, số, ký tự đặc biệt"
              required
              className="w-full pl-11 pr-11 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 rounded-xl text-neutral-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-600"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 cursor-pointer"
            >
              {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
            </button>
          </div>
          {errors.password && (
            <p className="text-xs text-red-500 mt-1">{errors.password[0]}</p>
          )}
        </div>

        {/* 4. Số điện thoại */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">
            Số điện thoại
          </label>
          <div className="relative">
            <Phone className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-neutral-400" />
            <input
              type="tel"
              name="phoneNumber"
              value={formData.phoneNumber}
              onChange={handleChange}
              placeholder="0912345678"
              className="w-full pl-11 pr-4 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 rounded-xl text-neutral-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-600"
            />
          </div>
          {errors.phoneNumber && (
            <p className="text-xs text-red-500 mt-1">{errors.phoneNumber[0]}</p>
          )}
        </div>

        {/* 5. Địa chỉ nhận hàng */}
        <div>
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1">
            Địa chỉ nhận hàng
          </label>
          <div className="relative">
            <MapPin className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-neutral-400" />
            <input
              type="text"
              name="address"
              value={formData.address}
              onChange={handleChange}
              placeholder="Số nhà, tên đường, phường/xã, quận/huyện"
              className="w-full pl-11 pr-4 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 rounded-xl text-neutral-900 dark:text-white text-sm focus:outline-none focus:ring-2 focus:ring-blue-600"
            />
          </div>
          {errors.address && (
            <p className="text-xs text-red-500 mt-1">{errors.address[0]}</p>
          )}
        </div>

        {/* Nút bấm Submit */}
        <button
          type="submit"
          disabled={isLoading}
          className="w-full mt-2 py-3 px-4 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-medium rounded-xl text-sm transition duration-200 flex items-center justify-center space-x-2 shadow-lg shadow-blue-600/30 cursor-pointer"
        >
          {isLoading ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              <span>Đang xử lý đăng ký...</span>
            </>
          ) : (
            <span>Đăng Ký Tài Khoản</span>
          )}
        </button>
      </form>

      {/* Đường dẫn sang trang Đăng nhập */}
      <div className="text-center mt-6">
        <p className="text-sm text-neutral-600 dark:text-neutral-400">
          Đã có tài khoản?{" "}
          <Link
            href="/login"
            className="text-blue-600 hover:text-blue-700 font-semibold hover:underline"
          >
            Đăng nhập ngay
          </Link>
        </p>
      </div>
    </div>
  );
}